UPDATE document_chunk c SET embedding=CAST(v.vector AS vector), embedding_model=#{model}, embedding_dimensions=#{dimensions}, embedding_content_hash=v.hash FROM (VALUES
(#{r.id},#{r.vector},#{r.contentHash})
) v(id,vector,hash) WHERE c.id=v.id AND c.document_id=#{id} AND c.document_version=#{version} AND NOT c.deleted AND c.chunk_type='CHILD'

mapper.select:
SELECT status
FROM document_version
WHERE document_id=#{id} AND version_no=#{version}
